from _lib import *
MM="Manuel des Monstres 5e (2014), entrée « %s »"
PHB="Manuel des Joueurs 5e (2014), "
D="Dans D&D 5e, "
W="The Wild Beyond the Witchlight (2021)"
C("fee-001",1,D+"quel plan est la demeure des fées ?",["La Féerie (Feywild)","Le plan Astral","Les Neuf Enfers","Mechanus"],"La Féerie est un plan brillant et sauvage, reflet du plan Matériel, où vivent les fées ; elle est reliée au monde par des « passages féeriques ».",D+"Guide du Maître (2014), chap. 2 « La Féerie »")
C("fee-002",2,D+"quelle fée mi-homme mi-bouc charme, effraie ou endort avec sa flûte ?",["Le satyre","Le centaure","Le gnoll","Le minotaure"],"Le satyre (FP 1/2) joue de la flûte de Pan : les créatures qui l’entendent doivent résister à un charme, à la peur ou au sommeil.",MM%"Satyre")
C("fee-003",2,D+"quelle fée est liée à un arbre dont elle ne peut s’éloigner longtemps ?",["La dryade","La pixie","Le sprite","La harpie"],"La dryade (FP 1) est liée à un arbre ; elle peut passer d’un arbre à un autre (Pas d’arbre) et parler aux plantes.",MM%"Dryade")
C("fee-004",1,D+"quelle fée porte une flûte et aime faire la fête ?",["Le satyre","Le gnoll","Le gobelin","Le troll"],"Le satyre est un fêtard : il possède des cornes, des sabots de bouc et un arc ; il vit dans la Féerie et les forêts où il danse et chante.",MM%"Satyre")
C("fee-005",2,D+"quelle minuscule fée peut devenir invisible et lancer des sorts innés ?",["La pixie","La dryade","Le satyre","La harpie"],"La pixie (FP 1/4) a 1 PV, des ailes, une invisibilité supérieure et des sorts innés (Confusion, Détection des pensées…).",MM%"Pixie")
C("fee-006",2,D+"quelle fée minuscule porte un arc et peut percevoir l’émotion d’une créature ?",["Le sprite","La dryade","Le satyre","Le dragon féerique"],"Le sprite (FP 1/4) est un petit archer ailé ; sa Vue du cœur lui révèle l’état émotionnel d’une créature touchée.",MM%"Sprite")
C("fee-007",2,D+"quelle guenaude change d’apparence et imite les voix ?",["La guenaude verte","La guenaude des mers","La guenaude nocturne","La banshee"],"La guenaude verte (FP 3) dispose d’Apparence illusoire et de Mimétisme (animaux et voix humanoïdes) pour attirer ses victimes.",MM%"Guenaude verte")
C("fee-008",2,D+"quelle fée ressemble à un chien et se téléporte ?",["Le chien clignotant","Le chien de l’enfer","Le worg","Le loup sanguinaire"],"Le chien clignotant (blink dog, FP 1/4) est une fée loyale bonne ; il se téléporte à courte portée en action bonus.",MM%"Chien clignotant")
C("fee-009",2,D+"quel protecteur d’occultiste est une puissance de la Féerie ?",["L’Archifée","Le Fiélon","Le Grand Ancien","Le Céleste"],"L’Archifée (Archfey) est un seigneur de la Féerie, capricieux et puissant ; il donne par exemple Pas de fée et Brume de la cour.",PHB+"chap. 3 « Occultiste », Archifée")
C("fee-010",3,D+"quelle sous-classe de rôdeur, présentée dans Tasha, est liée à la Féerie ?",["Le Vagabond féerique","Le Chasseur de monstres","L’Arpenteur d’horizon","Le Traqueur des ténèbres"],"Le Vagabond féerique (Fey Wanderer) tire sa force de la Féerie (charme, sorts de fées) ; les trois autres sont dans le Guide de Xanathar.",D+"Tasha’s Cauldron of Everything (2020), chap. 1, Rôdeur")
C("fee-011",2,D+"quel peuple elfique de la Féerie change de saison (printemps, été, automne, hiver) ?",["Les eladrins","Les drows","Les elfes sylvains","Les elfes de mer"],"Les eladrins ont un « Pas de fée » (Fey Step) qui les téléporte ; leur saison, qui change avec leur humeur, détermine leurs effets.",D+"Mordenkainen’s Tome of Foes (2018), chap. 3 « Eladrin »")
C("fee-012",2,D+"quel supplément de 2021 emmène les joueurs dans la Féerie ?",["The Wild Beyond the Witchlight","Candlekeep Mysteries","Icewind Dale : Rime of the Frostmaiden","Tomb of Annihilation"],"The Wild Beyond the Witchlight (2021) est une aventure de la Féerie pour des personnages de niveaux 1 à 8.",W+", introduction")
C("fee-013",3,D+"dans The Wild Beyond the Witchlight, quel événement sert de point de départ ?",["Le carnaval Witchlight","La foire de Waterdeep","Le bal de Baldur’s Gate","Le festival des moissons"],"Le carnaval Witchlight (Witchlight Carnival), un cirque itinérant, est une porte vers la Féerie.",W+", chap. 1")
C("fee-014",2,D+"quel dieu elfe est le créateur des elfes ?",["Corellon Larethian","Moradin","Gruumsh","Lolth"],"Corellon Larethian, chef du Seldarine, est le créateur des elfes ; Lolth, la Reine-Araignée, est la déesse des drows.",PHB+"chap. 2 « Elfe » ; Annexe B « Divinités »")
C("fee-015",2,D+"quel grand être végétal gardien des forêts n’est pas une fée mais une plante ?",["Le treant","La dryade","Le satyre","La pixie"],"Le treant (FP 9) est un arbre marcheur de type plante, gardien de la forêt ; la dryade, elle, est une fée.",MM%"Treant")
C("fee-016",2,D+"quel est le type de créature d’une dryade ?",["Fée","Plante","Humanoïde","Élémentaire"],"La dryade est une fée (type fey), de même que le satyre, la pixie et les guenaudes.",MM%"Dryade")
C("fee-017",3,D+"quel objet une guenaude nocturne protège-t-elle jalousement ?",["Sa pierre de cœur","Un bâton noir","Un œil de verre","Une cape d’ombre"],"La pierre de cœur (heartstone) permet à la guenaude nocturne de voyager vers l’Éthéré ; elle fait d’elle une créature redoutable.",MM%"Guenaude nocturne")
C("fee-018",3,D+"que permet un sabbat (coven) de trois guenaudes ?",["Lancer ensemble des sorts de sabbat","Voler sans balai","Être invisible en permanence","Ressusciter les morts"],"Un sabbat de trois guenaudes donne accès à des sorts partagés (Éclair, Bolt, Charme, Invisibilité…) que chacune peut lancer en groupe.",MM%"Sabbat de guenaudes")
C("fee-019",2,D+"quelle créature de la Féerie ressemble à un petit dragon farceur ?",["Le dragon féerique","Le pseudo-dragon","La wyverne","Le dragonnet"],"Le dragon féerique (faerie dragon) est un petit dragon coloré qui adore les farces ; il vit dans les forêts de la Féerie.",MM%"Dragon féerique")
C("fee-020",2,D+"quel plan est l’écho sombre du plan Matériel, souvent opposé à la Féerie ?",["Le Gisombre (Shadowfell)","Mechanus","Les Abysses","Le plan Astral"],"Le Gisombre est un plan de ténèbres et de mort ; la Féerie est lumineuse, mais tout aussi dangereuse.",D+"Guide du Maître (2014), chap. 2 « Le Gisombre »")
C("fee-021",2,D+"quel type de créature regroupe dryades, satyres, pixies et guenaudes ?",["Les fées","Les humanoïdes","Les plantes","Les élémentaires"],"Toutes ces créatures sont de type fée (fey), liées à la magie sauvage de la Féerie.",MM%"Fée")
C("fee-022",2,D+"que révèle la capacité Vue du cœur du sprite ?",["L’état émotionnel de la créature touchée","Ses souvenirs récents","Son nom véritable","Ses points de vie"],"En touchant une créature, le sprite sent si elle est bonne ou mauvaise et connaît son état émotionnel.",MM%"Sprite")
C("fee-023",3,D+"que permet la capacité Pas d’arbre de la dryade ?",["Se téléporter d’un arbre vivant à un autre","Parler aux animaux","Rendre un arbre vivant","Marcher sur l’eau"],"La dryade peut passer par un arbre et sortir d’un autre arbre vivant dans les 18 m, pour fuir ou surprendre.",MM%"Dryade")
C("fee-024",3,D+"quel est l’alignement du chien clignotant ?",["Loyal bon","Chaotique mauvais","Neutre strict","Chaotique bon"],"Le chien clignotant est loyal bon : il protège les innocents et combat les chiens-lézards ou les monstres mauvais.",MM%"Chien clignotant")
C("fee-025",2,D+"que peut faire la flûte du satyre ?",["Charmer, effrayer ou endormir","Faire apparaître un orage","Rendre invisible","Guérir ses alliés"],"Les flûtes du satyre (Charmer, Effrayer, Endormir) font tomber les créatures qui échouent un jet de sauvegarde de Sagesse.",MM%"Satyre")
C("fee-026",3,D+"quelle guenaude est la plus puissante (FP 5) ?",["La guenaude nocturne","La guenaude verte","La guenaude des mers","La banshee"],"La guenaude nocturne (night hag) est de FP 5 : elle tourmente les dormeurs et vole des âmes ; la verte est de FP 3 et celle des mers de FP 2.",MM%"Guenaude nocturne")
C("fee-027",3,"Dans les Royaumes Oubliés (D&D), quelle déesse elfe est liée à la lune et aux rêves ?",["Sehanine Moonbow","Mystra","Séluné","Corellon Larethian"],"Sehanine Moonbow, « Arc-en-lune », est la déesse elfique de la lune, des rêves et des voyages ; Séluné est la déesse humaine de la Lune.",D+"Forgotten Realms Wiki, article « Sehanine Moonbow »")
C("fee-028",3,D+"quel sort de niveau 6 permet d’invoquer une fée ?",["Convocation de fée","Convocation d’animaux","Convocation d’élémentaire","Convocation de céleste"],"Convocation de fée (Conjure Fey) est un sort de druide et de barde de niveau 6 ; la créature convoquée est de FP 6 au plus.",PHB+"chap. 11 « Sorts », Convocation de fée")
C("fee-029",3,D+"quel sort de niveau 4 convoque des fées pour combattre à vos côtés ?",["Convocation d’êtres sylvestres","Convocation d’élémentaire","Convocation de céleste","Convocation de fée"],"Convocation d’êtres sylvestres (Conjure Woodland Beings, niveau 4) convoque des fées de FP 2 au plus, en nombre variable selon leur FP.",PHB+"chap. 11 « Sorts », Convocation d’êtres sylvestres")
C("fee-030",2,D+"quel peuple jouable minuscule et ailé est introduit dans The Wild Beyond the Witchlight ?",["Les fées","Les aarakocras","Les tabaxis","Les kenkus"],"Les fées (fairies) sont de petite taille, volent à 9 m et lancent Lueurs féeriques ; les harengons font aussi leur apparition dans ce livre.",W+", chap. 1 « Peuples »")
V("fee-031",1,D+"la Féerie est un plan d’existence.",True,"Vrai : la Féerie (Feywild) est un plan de beauté sauvage et de magie capricieuse.",D+"Guide du Maître (2014), chap. 2")
