V("fee-039",2,D+"le dragon féerique est un énorme dragon.",False,"Faux : c’est un petit dragon (Tiny/Petit), espiègle et farceur.",MM%"Dragon féerique")
V("fee-040",2,D+"les eladrins changent de saison.",True,"Vrai : leur saison (printemps, été, automne, hiver) change avec leurs émotions.",D+"Mordenkainen’s Tome of Foes (2018), chap. 3 « Eladrin »")
V("fee-041",3,D+"le Gisombre est un autre nom de la Féerie.",False,"Faux : c’est un autre plan, sombre et lugubre.",D+"Guide du Maître (2014), chap. 2")
V("fee-042",3,D+"le peuple jouable des fées apparaît dans The Wild Beyond the Witchlight.",True,"Vrai : les fées (fairies) et les harengons y sont jouables.",W+", chap. 1")
V("fee-043",2,D+"l’Archifée est un protecteur d’occultiste.",True,"Vrai : avec le Fiélon et le Grand Ancien, c’est l’un des trois protecteurs du Manuel des Joueurs.",PHB+"chap. 3 « Occultiste »")
V("fee-044",2,D+"Corellon est le dieu des orcs.",False,"Faux : c’est le créateur des elfes ; le dieu des orcs est Gruumsh.",PHB+"Annexe B « Divinités »")
V("fee-045",3,D+"la guenaude nocturne est de FP 5.",True,"Vrai : FP 5, contre 3 pour la verte et 2 pour celle des mers.",MM%"Guenaude nocturne")
V("fee-046",3,D+"le treant est une fée.",False,"Faux : c’est une plante, gardienne de la forêt.",MM%"Treant")
V("fee-047",2,D+"la dryade peut se déplacer d’un arbre à un autre.",True,"Vrai : grâce à Pas d’arbre, elle passe d’un arbre vivant à un autre dans les 18 m.",MM%"Dryade")
V("fee-048",2,D+"le chien clignotant est d’alignement loyal bon.",True,"Vrai : il est bon et loyal.",MM%"Chien clignotant")
